<?php
if(current_user()['role']!=='Admin'){http_response_code(403);echo '<div class="alert danger">Administrator access required.</div>';return;}
if(!item_codes_ready()){echo '<div class="alert warn">Run <a href="upgrade_item_codes.php">Item Code Upgrade</a> first.</div>';return;}
try{$ref=$_GET['run']??'';$run=$ref?brand_sku_run($ref):null;$plan=$run?$run['plan']:brand_sku_plan();
echo '<div class="page-head"><div><h1>Brand SKU Format</h1><p>Brand + category + sequence. Code conversion only; stock and transaction history are preserved.</p></div><a class="btn ghost" href="?page=products">Product Master</a></div><div class="alert info">Examples: RS8-CB-0001, SRF-CB-0002, RS8-PS-0001. Each category has one sequence shared across brands. Old item codes remain aliases. Existing count sheets keep their original snapshot codes.</div><div class="card"><h3>'.($run?e($ref).' · '.e($run['status']):'Conversion Preview').'</h3><p>'.count($plan['lines']).' products · '.$plan['changed'].' codes to change. Includes inactive products.</p><p>Default brand prefixes: RS8, SRF, OLE (Oils &amp; Liquid Essentials), LPRO (Lumina Pro), MERCH (Merchandise), OTH (Others). Custom brands receive unique prefixes shown in the mapping.</p><div class="modal-actions"><a class="btn secondary" href="brand_sku_update.php?download=1'.($ref?'&run='.urlencode($ref):'').'">Download Old / New Codes Excel</a><a class="btn ghost" href="brand_sku_update.php?download=1&format=print'.($ref?'&run='.urlencode($ref):'').'" target="_blank" rel="noopener">Print / Save as PDF</a></div>';
if(!$run||$run['status']!=='Prepared'){if($run)echo '<div class="alert success">Conversion applied '.e($run['applied_at']).'. Stock balances were preserved.</div><a class="btn primary" href="report.php?report=product_master&format=xlsx">Download Updated Product Master</a>';echo '<form method="post" action="brand_sku_update.php" class="stack"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="prepare"><p>Pause product edits and transactions. Create a full backup, verify restoration, then review the saved mapping.</p><button class="btn secondary">Create Verified Backup &amp; Prepare Code Conversion</button></form>';}else{echo '<p>Verified backup #'.(int)$run['backup_id'].' · Prepared '.e($run['prepared_at']).'</p><form method="post" action="brand_sku_update.php" class="stack" data-confirm="Apply the reviewed brand/category item codes? Stocks and transaction records will be preserved."><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="apply"><input type="hidden" name="run" value="'.e($ref).'"><input type="hidden" name="digest" value="'.e($run['digest']).'"><label>Type APPLY BRAND SKU FORMAT<input name="confirmation" autocomplete="off" required></label><label class="ack"><input type="checkbox" name="review_ack" value="1" required> I reviewed the old/new mapping and verified backup.</label><button class="btn primary">Apply Brand SKU Format — Keep Stocks</button><a class="btn ghost" href="?page=brand_sku">Prepare a New Preview</a></form>';}
echo '</div><div class="card table-wrap"><h3>Old → New Master SKU</h3><p>The first 50 products appear below. Download Excel to review all products.</p><table class="table"><tr><th>Old SKU</th><th>New SKU</th><th>Product</th><th>Brand</th><th>Category</th></tr>';foreach(array_slice($plan['lines'],0,50) as $l)echo '<tr><td>'.e($l['old']).'</td><td><b>'.e($l['new']).'</b></td><td>'.e($l['name']).'</td><td>'.e(inventory_filter_brand($l['brand'])).'</td><td>'.e($l['sub']).'</td></tr>';echo '</table></div><div class="card"><h3>Code Conversion History</h3><table class="table"><tr><th>Reference</th><th>Status</th><th>Prepared / Applied</th><th>Backup</th><th></th></tr>';foreach(brand_sku_runs_ready()?db()->query("SELECT run_json FROM sku_conversion_runs ORDER BY created_at DESC,run_ref DESC LIMIT 30"):[] as $r){$h=json_decode($r['run_json'],true);if(!$h)continue;echo '<tr><td>'.e($h['ref']).'</td><td>'.e($h['status']).'</td><td>'.e($h['prepared_at'].' / '.($h['applied_at']??'')).'</td><td>#'.(int)$h['backup_id'].'</td><td><a class="btn ghost sm" href="?page=brand_sku&run='.e(urlencode($h['ref'])).'">View</a></td></tr>';}echo '</table></div>';
}catch(Throwable $e){echo '<div class="alert danger">'.e(safe_error_message($e)).'</div>';}
